package si.spindl.reports;

import si.spindl.common.exception.BadRequestException;
import si.spindl.common.exception.ConflictException;
import si.spindl.common.exception.ForbiddenException;
import si.spindl.common.exception.NotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import si.spindl.identity.TenantAuditEventEntity;
import si.spindl.identity.TenantAuditEventRepository;
import si.spindl.crm.LeadRepository;
import java.util.*;
import java.util.regex.Pattern;
import si.spindl.reports.LeadPipelineWorkflowDtos.PipelineConfig;
import si.spindl.reports.LeadPipelineWorkflowDtos.Transition;
import si.spindl.reports.LeadPipelineWorkflowDtos.PreviewResult;
import si.spindl.reports.LeadPipelineWorkflowDtos.ValidationResult;
import si.spindl.reports.LeadPipelineWorkflowDtos.WorkflowView;
import si.spindl.reports.LeadPipelineWorkflowDtos.VersionView;

@Service
public class LeadPipelineWorkflowService {
    public static final String WORKFLOW_KEY="crm_lead_pipeline";
    private static final Pattern STATE=Pattern.compile("[A-Z][A-Z0-9_]{1,23}");
    private static final Set<String> ROLES=Set.of("", "MANAGER", "ADMIN", "OWNER");
    private static final Set<String> LEGACY_STAGES=Set.of("NEW","QUALIFIED","PROPOSAL","WON","LOST");
    private final TenantWorkflowVersionRepository versions;private final TenantAuditEventRepository audit;private final LeadRepository leads;
    public LeadPipelineWorkflowService(TenantWorkflowVersionRepository versions,TenantAuditEventRepository audit,LeadRepository leads){this.versions=versions;this.audit=audit;this.leads=leads;}

    @Transactional(readOnly=true) public WorkflowView view(UUID tenantId){List<TenantWorkflowVersionEntity> history=versions.findAllByTenantIdAndWorkflowKeyOrderByVersionDesc(tenantId,WORKFLOW_KEY);return new WorkflowView(WORKFLOW_KEY,"Lead pipeline",history.stream().filter(v->v.getStatus().equals("PUBLISHED")).findFirst().map(LeadPipelineWorkflowMapper::toVersionView).orElse(null),history.stream().filter(v->v.getStatus().equals("DRAFT")).findFirst().map(LeadPipelineWorkflowMapper::toVersionView).orElse(null),history.stream().map(LeadPipelineWorkflowMapper::toVersionView).toList());}
    @Transactional public VersionView createDraft(UUID tenantId,UUID actor,PipelineConfig config){if(versions.existsByTenantIdAndWorkflowKeyAndStatus(tenantId,WORKFLOW_KEY,"DRAFT"))throw conflict("Finish or publish the existing draft first");validate(config);var entity=versions.save(new TenantWorkflowVersionEntity(tenantId,WORKFLOW_KEY,versions.findMaxVersion(tenantId,WORKFLOW_KEY)+1,toMap(config),actor));audit.save(new TenantAuditEventEntity(tenantId,actor,"LEAD_WORKFLOW_DRAFT_CREATED","workflow",entity.getId(),Map.of("key",WORKFLOW_KEY,"version",entity.getVersion())));return LeadPipelineWorkflowMapper.toVersionView(entity);}
    @Transactional public VersionView updateDraft(UUID tenantId,UUID actor,UUID id,PipelineConfig config){var entity=versions.findForUpdate(tenantId,id).filter(v->v.getWorkflowKey().equals(WORKFLOW_KEY)).orElseThrow(()->notFound());validate(config);entity.updateDraft(toMap(config));audit.save(new TenantAuditEventEntity(tenantId,actor,"LEAD_WORKFLOW_DRAFT_UPDATED","workflow",id,Map.of("version",entity.getVersion())));return LeadPipelineWorkflowMapper.toVersionView(entity);}
    @Transactional(readOnly=true) public ValidationResult validate(UUID tenantId,UUID id){PipelineConfig config=config(version(tenantId,id));List<String> errors=validationErrors(config);return new ValidationResult(errors.isEmpty(),errors.isEmpty()?List.of("All states are reachable from NEW.","Each transition has valid source, destination, and role.","WON and LOST business outcomes are present."):errors,config.states().size(),config.transitions().size());}
    @Transactional(readOnly=true) public PreviewResult preview(UUID tenantId,UUID id,String from,String to,String role){PipelineConfig config=config(version(tenantId,id));boolean stateExists=config.states().contains(from)&&config.states().contains(to);Transition transition=stateExists?config.transitions().stream().filter(t->t.from().equals(from)&&t.to().equals(to)).findFirst().orElse(null):null;boolean roleMatches=transition!=null&&(transition.requiredRole().isBlank()||transition.requiredRole().equals(role)||Set.of("OWNER","ADMIN").contains(role));return new PreviewResult(from,to,role,transition!=null,roleMatches,transition==null?"Transition is not configured":roleMatches?"Transition is available":"The assigned role is required: "+transition.requiredRole());}
    @Transactional public VersionView publish(UUID tenantId,UUID actor,UUID id){var entity=versions.findForUpdate(tenantId,id).filter(v->v.getWorkflowKey().equals(WORKFLOW_KEY)).orElseThrow(()->notFound());PipelineConfig config=config(entity);List<String> errors=validationErrors(config);List<String> usedStages=leads.findDistinctStagesByTenantId(tenantId);if(!config.states().containsAll(usedStages))errors.add("The workflow must retain stages currently used by leads: "+String.join(", ",usedStages.stream().filter(stage->!config.states().contains(stage)).toList())+".");if(!errors.isEmpty())throw badRequest(String.join(" ",errors));versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,WORKFLOW_KEY,"PUBLISHED").ifPresent(TenantWorkflowVersionEntity::rollback);entity.publish();audit.save(new TenantAuditEventEntity(tenantId,actor,"LEAD_WORKFLOW_PUBLISHED","workflow",id,Map.of("version",entity.getVersion())));return LeadPipelineWorkflowMapper.toVersionView(entity);}
    @Transactional public WorkflowView rollback(UUID tenantId,UUID actor){var current=versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,WORKFLOW_KEY,"PUBLISHED").orElseThrow(()->conflict("There is no published lead workflow to roll back"));var prior=versions.findAllByTenantIdAndWorkflowKeyOrderByVersionDesc(tenantId,WORKFLOW_KEY).stream().filter(v->v.getVersion()<current.getVersion()&&v.getStatus().equals("ROLLED_BACK")).findFirst().orElseThrow(()->conflict("There is no earlier version to restore"));current.rollback();prior.republish();audit.save(new TenantAuditEventEntity(tenantId,actor,"LEAD_WORKFLOW_ROLLED_BACK","workflow",prior.getId(),Map.of("fromVersion",current.getVersion(),"toVersion",prior.getVersion())));return view(tenantId);}
    @Transactional(readOnly=true) public boolean supportsStage(UUID tenantId,String stage){var active=versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,WORKFLOW_KEY,"PUBLISHED").orElse(null);return active==null?LEGACY_STAGES.contains(stage):config(active).states().contains(stage);}
    @Transactional(readOnly=true) public void requireTransition(UUID tenantId,UUID actorId,String from,String to,String role){var active=versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,WORKFLOW_KEY,"PUBLISHED").orElse(null);if(active==null)return;PipelineConfig config=config(active);if(!config.states().contains(to))throw badRequest("Choose a configured lead stage");PreviewResult result=preview(tenantId,active.getId(),from,to,role);if(!result.transitionExists())throw conflict("This lead cannot move from "+from+" to "+to+" under the published workflow");if(!result.allowed())throw new ForbiddenException(result.message());}
    private List<String> validationErrors(PipelineConfig config){List<String> errors=new ArrayList<>();if(config==null){errors.add("Workflow configuration is required.");return errors;}if(config.states()==null||config.states().size()<3||config.states().size()>12){errors.add("Choose between 3 and 12 stages.");return errors;}if(config.states().stream().anyMatch(value->value==null||!STATE.matcher(value).matches())||config.states().stream().distinct().count()!=config.states().size())errors.add("Stage names must be unique uppercase identifiers of 2–24 letters, numbers, or underscores.");if(!config.states().containsAll(List.of("NEW","WON","LOST")))errors.add("NEW, WON, and LOST stages are required for lead creation and conversion.");if(!"NEW".equals(config.initialState())||!config.states().contains(config.initialState()))errors.add("The initial stage must be NEW.");if(config.transitions()==null||config.transitions().size()<2||config.transitions().size()>40)errors.add("Choose between 2 and 40 transitions.");else{Set<String> edges=new HashSet<>();Map<String,Set<String>> graph=new HashMap<>();for(Transition t:config.transitions()){if(t==null||!config.states().contains(t.from())||!config.states().contains(t.to())||t.from().equals(t.to())){errors.add("Every transition needs two different configured stages.");continue;}if(!ROLES.contains(t.requiredRole()))errors.add("Transition roles must be any member, MANAGER, ADMIN, or OWNER.");if(!edges.add(t.from()+"->"+t.to()))errors.add("Duplicate transitions are not allowed.");graph.computeIfAbsent(t.from(),key->new HashSet<>()).add(t.to());}Set<String> reachable=new HashSet<>();Deque<String> queue=new ArrayDeque<>();queue.add(config.initialState());while(!queue.isEmpty()){String state=queue.removeFirst();if(reachable.add(state))queue.addAll(graph.getOrDefault(state,Set.of()));}if(!reachable.containsAll(config.states()))errors.add("Every configured stage must be reachable from NEW.");}return errors;}
    private void validate(PipelineConfig config){List<String> errors=validationErrors(config);if(!errors.isEmpty())throw badRequest(String.join(" ",errors));}
    private Map<String,Object> toMap(PipelineConfig config){List<Map<String,String>> transitions=config.transitions().stream().map(t->Map.of("from",t.from(),"to",t.to(),"requiredRole",t.requiredRole()==null?"":t.requiredRole())).toList();return Map.of("initialState",config.initialState(),"states",List.copyOf(config.states()),"transitions",transitions);}
    private PipelineConfig config(TenantWorkflowVersionEntity entity){Map<String,Object> values=entity.getConfiguration();List<String> states=((List<?>)values.get("states")).stream().map(String::valueOf).toList();List<Transition> transitions=((List<?>)values.get("transitions")).stream().map(row->{Map<?,?> item=(Map<?,?>)row;Object requiredRole=item.get("requiredRole");return new Transition(String.valueOf(item.get("from")),String.valueOf(item.get("to")),requiredRole==null?"":String.valueOf(requiredRole));}).toList();return new PipelineConfig(String.valueOf(values.get("initialState")),states,transitions);}
    private TenantWorkflowVersionEntity version(UUID tenantId,UUID id){return versions.findById(id).filter(v->v.getTenantId().equals(tenantId)&&v.getWorkflowKey().equals(WORKFLOW_KEY)).orElseThrow(()->notFound());}
    private ResponseStatusException badRequest(String text){return new BadRequestException(text);}private ResponseStatusException conflict(String text){return new ConflictException(text);}private ResponseStatusException notFound(){return new NotFoundException("Lead workflow version not found");}
}
